@implements IDisposable
@inject AuthenticationStateProvider AuthenticationStateProvider
@inject PersistentComponentState PersistentComponentState

@code {
    private PersistingComponentStateSubscription _subscription;

    protected override void OnInitialized()
    {
        _subscription = PersistentComponentState.RegisterOnPersisting(OnPersistingAsync, RenderMode.InteractiveWebAssembly);
    }

    private async Task OnPersistingAsync()
    {
        var authState = await AuthenticationStateProvider.GetAuthenticationStateAsync();
        var principal = authState.User;

        if (principal.Identity?.IsAuthenticated == true)
        {
            var email = principal.FindFirst(System.Security.Claims.ClaimTypes.Email)?.Value
                        ?? principal.Identity.Name ?? "";
            var roles = principal.FindAll(System.Security.Claims.ClaimTypes.Role)
                                 .Select(c => c.Value).ToArray();

            PersistentComponentState.PersistAsJson(nameof(UserInfo), new UserInfo
            {
                Email = email,
                Roles = roles
            });
        }
    }

    public void Dispose()
    {
        _subscription.Dispose();
    }
}

